mapper.select:
SELECT * FROM base_dict WHERE id IN #{id}
AND ((scope_type=0 AND family_group_id=0 AND user_id=#{userId})
OR (#{groupId}>0 AND scope_type=1 AND family_group_id=#{groupId} AND user_id=0)) ORDER BY id FOR UPDATE

mapper.update:
UPDATE base_dict SET dict_status=#{dictStatus},sort=#{sort},revision=revision+1,update_time=NOW()
WHERE id=#{id} AND user_id=#{userId} AND scope_type=#{scopeType} AND family_group_id=#{familyGroupId}
AND deleted=0 AND revision=#{revision}

UPDATE base_dict SET deleted=1,revision=revision+1,update_time=NOW()
WHERE id=#{id} AND user_id=#{userId} AND scope_type=#{scopeType} AND family_group_id=#{familyGroupId}
AND deleted=0 AND revision=#{revision}
